body:
I've prepared an example which will help you to understand what I mean.
When I try to align text to the right edge with fractional outline increments the text is crawling.
Does not matter whether I align to outline or to text body.
With `getLocalBounds()` returning size without outline it would've been cleaner. We could always add the outline value back instead of counting advance of outlined glyphs to keep the current behaviour.

```cpp
#include <SFML/Window.hpp>
#include <SFML/Graphics.hpp>

int main(int argc, char *argv[])
{
    sf::RenderWindow window;
    window.create(sf::VideoMode({800, 600}, 32), "SFML test");
    window.setVerticalSyncEnabled(true);
    window.setMouseCursorVisible(true);

    sf::Font font;
    std::vector<sf::Text> text;

    if(!font.loadFromFile("segoeui.ttf"))
        return EXIT_FAILURE;

    text.push_back(sf::Text("Lorem ipsum dolor sit amet,", font));
    text.push_back(sf::Text("consectetur adipiscing elit. Nam id", font));
    text.push_back(sf::Text("nisi id libero hendrerit eleifend. Sed", font));
    text.push_back(sf::Text("tincidunt vitae neque maximus", font));
    text.push_back(sf::Text("imperdiet.", font));

    int outline = 0;
    float lineHeight = 40;
    int alignMode = 0;

    int pos = 0;
    for (auto& t : text)
    {
        t.setCharacterSize(27);
        t.setFillColor(sf::Color::White);
        t.setPosition(sf::Vector2f(100.0, 100.0 + pos));
        pos += lineHeight;
    }

    sf::RectangleShape rect1, rect2;
    rect1.setFillColor(sf::Color(0, 0, 0, 75));
    rect2.setFillColor(sf::Color(0, 0, 0, 75));
    rect1.setSize(sf::Vector2f(500.0, 200.0));
    rect2.setSize(sf::Vector2f(500.0, 200.0));
    rect1.setPosition(sf::Vector2f(150.0, 75.0));
    rect2.setPosition(sf::Vector2f(150.0, 325.0));

    while (window.isOpen())
    {
        sf::Event event;
        while (window.pollEvent(event))
        {
            if (event.type == sf::Event::Closed)
                window.close();
            if (event.type == sf::Event::KeyPressed)
            {
                // Switch alignment to text body, or to outline
                if (event.key.code == sf::Keyboard::Space)
                    alignMode = 1 - alignMode;

                // Increase text outline
                if (event.key.code == sf::Keyboard::Down)
                {
                    outline++;
                    for (auto& t : text) t.setOutlineThickness(outline * 0.2);
                }

                // Decrease text outline
                if (event.key.code == sf::Keyboard::Up)
                {
                    outline--;
                    if ( outline < 0 ) outline = 0;
                    for (auto& t : text) t.setOutlineThickness(outline * 0.2);
                }

                if (event.key.code == sf::Keyboard::Escape)
                {
                    window.close();
                    return EXIT_SUCCESS;
                }
            }
        }

        window.clear(sf::Color(100, 100, 200, 255));

        // Align left
        for ( int i = 0; i < text.size(); i++ )
        {
            float ol = std::ceil(text[i].getOutlineThickness()) * alignMode;
            text[i].setPosition(sf::Vector2f(rect1.getPosition().x - text[i].getLocalBounds().left - ol,
                                             rect1.getPosition().y + i * lineHeight - text[i].getLocalBounds().top - ol));
            window.draw(text[i]);
        }

        // Align right
        for ( int i = 0; i < text.size(); i++ )
        {
            float ol = std::ceil(text[i].getOutlineThickness()) * alignMode;
            text[i].setPosition(sf::Vector2f(rect2.getPosition().x + rect2.getSize().x - text[i].getLocalBounds().width - text[i].getLocalBounds().left + ol,
                                             rect2.getPosition().y + i * lineHeight - text[i].getLocalBounds().top - ol));
            window.draw(text[i]);
        }

        window.draw(rect1);
        window.draw(rect2);

        window.display();
    }
    return EXIT_SUCCESS;
}
```

Down - Increases text outline by 0.2
Up - Decreases text outline by 0.2
Space - changes the align mode
